<?php
require_once __DIR__ . '/../includes/auth.php';require_admin();$pdo=db();
$events=$pdo->query('SELECT id,title,code,event_date FROM events ORDER BY event_date DESC,id DESC')->fetchAll();
$eventId=(int)($_GET['event_id']??0);$event=$eventId?get_event_by_id($eventId):null;
if(isset($_GET['export_summary'])&&$event){
  $cats=event_category_means($eventId);$qs=event_question_stats($eventId);$overall=event_overall_mean($eventId);$count=response_count($eventId);
  header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="summary-'.preg_replace('/[^A-Za-z0-9_-]/','_',$event['code']).'.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['Event',$event['title']]);fputcsv($out,['Code',$event['code']]);fputcsv($out,['Respondents',$count]);fputcsv($out,['Overall Mean',number_format($overall,2),mean_interpretation($overall)]);fputcsv($out,[]);fputcsv($out,['Category','Mean','Interpretation']);foreach($cats as $c){$m=(float)($c['mean_score']?:0);fputcsv($out,[$c['name'],$c['mean_score']!==null?number_format($m,2):'',mean_interpretation($m)]);}fputcsv($out,[]);fputcsv($out,['Question','Mean','Interpretation']);foreach($qs as $q){if($q['question_type']!=='likert')continue;$m=(float)($q['mean_score']?:0);fputcsv($out,[$q['question_text'],$q['mean_score']!==null?number_format($m,2):'',mean_interpretation($m)]);}fclose($out);exit;
}
$respondents=$event?response_count($eventId):0;$overall=$event?event_overall_mean($eventId):0;$categories=$event?event_category_means($eventId):[];$qstats=$event?event_question_stats($eventId):[];$profileTypes=[];if($event){$pst=$pdo->prepare("SELECT COALESCE(NULLIF(participant_type,''),'Not specified') AS label,COUNT(*) AS total FROM respondents WHERE event_id=? GROUP BY COALESCE(NULLIF(participant_type,''),'Not specified') ORDER BY total DESC");$pst->execute([$eventId]);$profileTypes=$pst->fetchAll();}
$comments=[];if($event){$st=$pdo->prepare("SELECT q.question_text,ra.answer_text FROM response_answers ra JOIN questions q ON q.id=ra.question_id JOIN respondents r ON r.id=ra.respondent_id WHERE r.event_id=? AND q.question_type IN ('paragraph','short_answer') AND COALESCE(TRIM(ra.answer_text),'')<>'' ORDER BY q.id,ra.id");$st->execute([$eventId]);foreach($st as $row)$comments[$row['question_text']][]=$row['answer_text'];}
$likert=array_values(array_filter($qstats,fn($q)=>$q['question_type']==='likert'&&$q['mean_score']!==null));usort($likert,fn($a,$b)=>(float)$b['mean_score']<=>(float)$a['mean_score']);$strengths=array_slice($likert,0,3);$improvements=array_slice(array_reverse($likert),0,3);
$pageTitle='Reports';$adminArea=true;require __DIR__.'/../includes/header.php';
?>
<div class="section-title no-print"><div><h1>Evaluation Reports</h1><p>Generate a printable event evaluation report and export summary data.</p></div></div>
<div class="card card-pad no-print"><form method="get"><label>Select Event</label><select name="event_id" onchange="this.form.submit()" style="max-width:620px;margin-top:6px"><option value="0">Choose an event</option><?php foreach($events as $e): ?><option value="<?= (int)$e['id'] ?>" <?= $eventId===(int)$e['id']?'selected':'' ?>><?= h($e['title']) ?> — <?= h(date('M j, Y',strtotime($e['event_date']))) ?></option><?php endforeach; ?></select></form></div>
<?php if($event): ?>
<div class="actions no-print" style="margin:16px 0"><button onclick="window.print()">Print Report</button><a class="btn ghost" href="reports.php?event_id=<?= $eventId ?>&export_summary=1">Export Summary CSV</a><a class="btn ghost" href="responses.php?event_id=<?= $eventId ?>&export=csv">Export Responses CSV</a></div>
<div class="panel">
<div class="report-header"><div class="eyebrow"><?= h(setting('organization_name','Your Institution')) ?></div><h1>Event Evaluation Report</h1><p class="muted" style="margin-bottom:0"><?= h($event['title']) ?></p></div>
<div class="report-section"><h2>1. Event Information</h2><div class="grid grid-3"><div><strong>Event Code</strong><div class="muted"><?= h($event['code']) ?></div></div><div><strong>Type</strong><div class="muted"><?= h($event['event_type']) ?></div></div><div><strong>Date</strong><div class="muted"><?= h(date('F j, Y',strtotime($event['event_date']))) ?></div></div><div><strong>Venue</strong><div class="muted"><?= h($event['venue']?:'—') ?></div></div><div><strong>Organizer</strong><div class="muted"><?= h($event['organizer']?:'—') ?></div></div><div><strong>Speaker/Facilitator</strong><div class="muted"><?= h($event['speaker']?:'—') ?></div></div></div></div>
<div class="report-section"><h2>2. Respondents and Overall Evaluation</h2><div class="grid grid-3"><div class="stat-card"><div class="stat-label">Respondents</div><div class="stat-value"><?= $respondents ?></div></div><div class="stat-card"><div class="stat-label">Overall Mean</div><div class="stat-value"><?= number_format($overall,2) ?></div></div><div class="stat-card"><div class="stat-label">Interpretation</div><div class="stat-value" style="font-size:1.35rem"><?= h(mean_interpretation($overall)) ?></div></div></div></div>
<div class="report-section"><h2>3. Respondent Profile</h2><?php if(!$profileTypes): ?><p class="muted">No respondent profile data available.</p><?php else: ?><div class="grid grid-3"><?php foreach($profileTypes as $p): ?><div class="stat-card"><div class="stat-label"><?= h($p['label']) ?></div><div class="stat-value"><?= (int)$p['total'] ?></div><div class="stat-note"><?= $respondents>0?number_format(((int)$p['total']/$respondents)*100,1):0 ?>% of respondents</div></div><?php endforeach; ?></div><?php endif; ?></div>
<div class="report-section"><h2>4. Category Ratings</h2><div class="grid" style="gap:10px;margin-bottom:16px"><?php foreach($categories as $c): $m=(float)($c['mean_score']?:0); $pct=min(100,max(0,($m/5)*100)); ?><div><div style="display:flex;justify-content:space-between;gap:12px"><strong><?= h($c['name']) ?></strong><span><?= $c['mean_score']!==null?number_format($m,2):'—' ?></span></div><div class="progress" style="margin-top:5px"><span style="--w:<?= number_format($pct,2,'.','') ?>%"></span></div></div><?php endforeach; ?></div><div class="table-wrap"><table class="table"><thead><tr><th>Category</th><th class="text-right">Mean</th><th>Interpretation</th></tr></thead><tbody><?php foreach($categories as $c): $m=(float)($c['mean_score']?:0); ?><tr><td><?= h($c['name']) ?></td><td class="text-right"><?= $c['mean_score']!==null?number_format($m,2):'—' ?></td><td><?= h(mean_interpretation($m)) ?></td></tr><?php endforeach; ?></tbody></table></div></div>
<div class="report-section"><h2>5. Question-Level Results</h2><div class="table-wrap"><table class="table"><thead><tr><th>Question</th><th>Category</th><th class="text-right">Mean</th><th>Interpretation</th></tr></thead><tbody><?php foreach($qstats as $q): if($q['question_type']!=='likert')continue;$m=(float)($q['mean_score']?:0); ?><tr><td style="white-space:normal"><?= h($q['question_text']) ?></td><td><?= h($q['category_name']?:'General') ?></td><td class="text-right"><?= $q['mean_score']!==null?number_format($m,2):'—' ?></td><td><?= h(mean_interpretation($m)) ?></td></tr><?php endforeach; ?></tbody></table></div></div>
<div class="report-section"><h2>6. Strengths</h2><?php if(!$strengths): ?><p class="muted">No rating data available.</p><?php else: ?><ol><?php foreach($strengths as $q): ?><li><?= h($q['question_text']) ?> — <strong><?= number_format((float)$q['mean_score'],2) ?></strong> (<?= h(mean_interpretation((float)$q['mean_score'])) ?>)</li><?php endforeach; ?></ol><?php endif; ?></div>
<div class="report-section"><h2>7. Areas for Improvement</h2><?php if(!$improvements): ?><p class="muted">No rating data available.</p><?php else: ?><ol><?php foreach($improvements as $q): ?><li><?= h($q['question_text']) ?> — <strong><?= number_format((float)$q['mean_score'],2) ?></strong> (<?= h(mean_interpretation((float)$q['mean_score'])) ?>)</li><?php endforeach; ?></ol><?php endif; ?></div>
<div class="report-section"><h2>8. Participant Comments and Recommendations</h2><?php if(!$comments): ?><p class="muted">No qualitative comments submitted.</p><?php else: foreach($comments as $q=>$items): ?><h3><?= h($q) ?></h3><ul><?php foreach($items as $text): ?><li><?= h($text) ?></li><?php endforeach; ?></ul><?php endforeach; endif; ?></div>
<div class="report-section"><h2>9. Summary and Recommendations</h2><p>The event received <strong><?= $respondents ?></strong> evaluation response<?= $respondents===1?'':'s' ?> with an overall mean rating of <strong><?= number_format($overall,2) ?></strong>, interpreted as <strong><?= h(mean_interpretation($overall)) ?></strong>. The listed strengths and areas for improvement are based strictly on the highest and lowest mean Likert items recorded in the system. Organizers should retain the highest-rated practices and prioritize review of the lowest-rated items together with the qualitative participant comments above when planning future programs.</p></div>
</div>
<?php endif; ?>
<?php require __DIR__.'/../includes/footer.php'; ?>
